\begin{itemchoice}
				\itemch Phép trừ $17 - 5 = 12$. (Đúng)
				\itemch Phép cộng $14 + 5 = 19$. Số $19$ không lớn hơn $20$. (Sai)
				\itemch Phép cộng $10 + 10 = 20$. (Đúng)
				\itemch Phép trừ $18 - 4 = 14$. Số $14$ không bé hơn $13$. (Sai)
			\end{itemchoice}

\begin{itemchoice}
				\itemch Hình chữ nhật có $4$ cạnh. (Sai)
				\itemch Hình vuông có đúng $4$ cạnh bằng nhau. (Đúng)
				\itemch Hình tròn (hoặc khối cầu) không có góc cạnh nên có thể lăn được. (Đúng)
				\itemch Khối rubik có dạng khối lập phương, không phải hình chữ nhật. (Sai)
			\end{itemchoice}

\begin{itemchoice}
				\itemch Tuần mới bắt đầu bằng Thứ Hai ngay sau Chủ Nhật. (Đúng)
				\itemch Một ngày đêm có $24$ giờ. (Sai)
				\itemch Kim phút (kim dài) chạy nhanh hơn kim giờ (kim ngắn). (Đúng)
				\itemch $12$ giờ là thời điểm chính giữa buổi trưa. (Đúng)
			\end{itemchoice}

\begin{itemchoice}
				\itemch Số liền sau $19$ là $19 + 1 = 20$. (Đúng)
				\itemch Số lớn nhất có một chữ số là số $9$. (Sai)
				\itemch Các số $2, 4, 6, 8$ đều chia hết cho $2$ nên là số chẵn. (Đúng)
				\itemch Số $15$ gồm $1$ chục và $5$ đơn vị. (Sai)
			\end{itemchoice}
